python3 -c "
import csv
from decimal import Decimal
p={r['product_id'].strip():r for r in csv.DictReader(open('/data/products.csv'))}
t={}
for r in csv.DictReader(open('/data/orders.csv')):
    pr=p.get(r['product_id'].strip())
    if not pr: print('unmatched',r); continue
    c=pr['category'].strip()
    t[c]=t.get(c,0)+Decimal(r['quantity'])*Decimal(pr['price'])
for c,v in sorted(t.items(),key=lambda x:-x[1]): print(f'{c}: {v}')
"

